TLM.f("Sancti/12-06",{"officium":"S. Nicolai Episcopi et Confessoris","rule":["vide C4;","Gloria"],"fallback":"Commune/C4","from":{"GradualeP":"Commune/C4","Tractus":"Commune/C4"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 45:30"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 131:1"},{"k":"text","la":"Meménto, Dómine, David: et omnis mansuetúdinis ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui beátum Nicoláum Pontíficem innúmeris decorásti miráculis: tríbue, quǽsumus; ut ejus méritis et précibus a gehénnæ incéndiis liberémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","la":"Hebr 13:7-17"},{"k":"text","la":"Fratres: Mementóte præpositórum vestrórum, qui vobis locúti sunt verbum Dei: quorum intuéntes éxitum conversatiónis, imitámini fidem. Jesus Christus heri et hódie: ipse et in sǽcula. Doctrínis váriis et peregrínis nolíte abdúci. Optimum est enim grátia stabilíre cor, non escis, quæ non profuérunt ambulántibus in eis. Habémus altáre, de quo édere non habent potestátem, qui tabernáculo deserviunt. Quorum enim animálium infértur sanguis pro peccáto in Sancta per pontíficem, horum córpora cremántur extra castra. Propter quod et Jesus, ut sanctificáret per suum sánguinem pópulum, extra portam passus est. Exeámus ígitur ad eum extra castra, impropérium ejus portántes. Non enim habémus hic manéntem civitátem, sed futúram inquírimus. Per ipsum ergo offerámus hóstiam laudis semper Deo, id est fructum labiórum confiténtium nómini ejus. Beneficéntiæ autem et communiónis nolíte oblivísci: tálibus enim hóstiis promerétur Deus. Obœdíte præpósitis vestris et subjacéte eis. Ipsi enim pervígilant, quasi ratiónem pro animábus vestris redditúri."}],"Graduale":[{"k":"ref","la":"Ps 88:21-23"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum."},{"k":"text","la":"Nihil profíciet inimícus in eo, et fílius iniquitátis non nocébit ei.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."},{"k":"text","la":"Hic est sacérdos, quem coronávit Dóminus. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi."},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 25:14-23"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Homo péregre proficíscens vocávit servos suos, et trádidit illis bona sua. Et uni dedit quinque talénta, álii autem duo, álii vero unum, unicuíque secúndum própriam virtútem, et proféctus est statim. Abiit autem, qui quinque talénta accéperat, et operátus est in eis, et lucrátus est ália quinque. Simíliter et, qui duo accéperat, lucrátus est ália duo. Qui autem unum accéperat, ábiens fodit in terram, et abscóndit pecúniam dómini sui. Post multum vero témporis venit dóminus servórum illórum, et pósuit ratiónem cum eis. Et accédens qui quinque talénta accéperat, óbtulit ália quinque talénta, dicens: Dómine, quinque talénta tradidísti mihi, ecce, ália quinque superlucrátus sum. Ait illi dóminus ejus: Euge, serve bone et fidélis, quia super pauca fuísti fidélis, super multa te constítuam: intra in gáudium dómini tui. Accéssit autem et qui duo talénta accéperat, et ait: Dómine, duo talénta tradidísti mihi, ecce, ália duo lucrátus sum. Ait illi dóminus ejus: Euge, serve bone et fidélis, quia super pauca fuísti fidélis, super multa te constítuam: intra in gáudium dómini tui."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Sanctífica, quǽsumus, Dómine Deus, hæc múnera, quæ in sollemnitáte sancti Antístitis tui Nicolái offérimus: ut per ea vita nostra inter advérsa et próspera úbique dirigátur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 88:36; 88:37-38"},{"k":"text","la":"Semel jurávi in sancto meo: Semen ejus in ætérnum manébit: et sedes ejus sicut sol in conspéctu meo, et sicut luna perfécta in ætérnum, et testis in coelo fidélis. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Sacrifícia, quæ súmpsimus, Dómine, pro sollemnitáte sancti Pontíficis tui Nicolái, sempitérna nos protectióne consérvent."},{"k":"macro","name":"Per Dominum"}]},"hr":{"c02c414c737dacfd":{"t":"Sir 45, 30, Ps 131, 1\n(Sir 45, 30) Sklopio je Gospodin s njime savez mira učinio ga knezom da zauvijek bude u svećeničkom dostojanstvu. (Ps 131, 1) Spomeni se, Gospodine, Davida i sve njegove krotkosti.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 45, 30) Sklopio je Gospodin s njime savez mira učinio ga knezom da zauvijek bude u svećeničkom dostojanstvu.","kn":"(Grkv. 45, 30). Gospodin je sklopio s njime savez mira i učinio ga knezom, da zauvijek bude u svećeničkom dostojanstvu. (Ps. 131, 1). Sjeti se, Gospodine, Davida i sve njegove pobožnosti. Slava Ocu. Gospodin ...","knRef":"Kniewald 1942, str. 478–479 (snimka 240) (OCR)"},"ae52161e8c05b26a":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženog Nikolu biskupa ukrasio nebrojenim čudesima, daj da se njegovim zaslugama i molitvama oslobodimo od paklenog ognja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si blaženoga Nikolu, biskupa, ukrasio nebrojenim čudesima; podaj, molimo Te, Sv. Ambrozije 7. XII. da nas njegove zasluge i molitve izbave od paklenih plamena. Po G. n.","knRef":"Kniewald 1942, str. 450–451 (snimka 226) (OCR)"},"de96361ccef0874f":{"t":"Heb 13, 7-17\nČitanje Poslanice bl. Pavla apostola Hebrejima. Braćo, sjećajte se svojih pretpostavljenih, koji su vara propovijedali Božju nauku. Slijedite ih u vjeri i promatrajte svršetak njihova života. Isus Krist je isti jučer i danas i uvijek. Nemojte se zavoditi promjenljivim stranim naukama. Bolje je krijepiti srce milošću, a ne jelima, koja nisu koristila onima koji su ih uživali. Mi imamo žrtvenik s kojeg ne smiju jesi i službenici šatora. Kao što se tjelesa životinja kojih krv za grijehe unosi veliki svećenik u svetište spaljuju izvan šatora, tako je Krist, trpio izvan vrata da svojom krvlju posveti narod. Stoga pođimo izvan vrata noseći njegovu sramotu. Jer ovdje nemamo trajnoga boravišta, nego težimo za onim budućim. Prikazujmo po njem Bogu uvijek zahvalnu žrtvu, plod naših usana što priznaju njegovo ime. Ne zaboravljajte dobročinstva i milostinje, jer se takvim žrtvama stječu zasluge kod Boga. Slušajte svoje poglavare i pokoravajte im se, jer oni bdiju kao oni koji imaju polagati račun za vas.","kn":"Čitanje poslanice bi. Pavla apostola Hebrejima (13, 7-17). Braćol Sjećate li se svojih ipretpostavljenih, koji su vam propovijedali Božju nauku. Slijedite ih u vjeri motreći svršetak njihova života. Isus Krist isti je jučer i danas i u vijeke. Ne dajte se zavesti promjenljivim 1 stranim naukama. Najbolje je utvrditi svoje srce milošću, a ne jelima, koja nijesu koristila onima, koji su se ravnali po njima. Imamo žrtvenik, s kojega ne mogu Jesti oni, koji služe šatoru. Jer se izvan šatora, spaljuju tjeiesa onih životinja, kojih krv veliki svećenik unosi za grijeh u svetište. Zato je Isus, da svojom krvlju posveti narod, l trpio izvan vrata. Izađimo zato k njemu izvan šatora i nosimo njegovu sramotu. Jer ovdje nemamo trajnoga bO'ravišta, nego težimo za onim, što dolazi. Po njemu prinosimo uvijek Bogu zahvalnu žrtvu, kao plod usana, što ispovijedaju njegovo ime. A nemojte zaboraviti na dobročinstva i milostinje, jer* se takvim žrtvama stječu zasluge kod Boga. Slušajte svoje poglavare i pokoravajte im se, jer oni bdiju kao oni, koji će davati račun za vaše duše.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"9be2a0d95052a22a":{"t":"Ps 88, 21-23\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja. Neprijatelj biti nemoćan prema njemu, i sin bezakonja neće se usuditi da mu naškodi.\n\nPs 91, 13\n<i>Aleluja</i>, <i>aleluja</i>.\nKao palma cvjeta i kao libanski cedar raste pravednik. <i>Aleluja</i>.","kn":"(Ps. 88, 21-23). Izabrah Davida slu- ,gu moga i pomazah ga uljem svetim; jer ruka moja (Ppmoze njemu i moja ga mišica jača. Neprijatelj mu ne će ništa naškoditi i sin zloće ne će mu nauditi.\n\nAleluja, aleluja. (Ps. 91, 13.) Pravednik cvate kao paoma i raste poput libanonskog cedra, aleluja.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"b87a2aadbcf6e431":{"t":"Mt 25, 14-23\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima ovu usporedbu: Čovjek koji kreće na put pozove svoje sluge i preda im svoj imetak. Jednomu dade pet talenata, drugome dva, a trećemu jedan: svakomu prema njegovoj sposobnosti. I odmah otputuje. Onaj koji je primio pet talenata ode da s njima radi i stječe drugih pet. Tako i koji je primio dva steče s njima druga dva. A koji je primio jedan, ode, zakopa i sakrije novac svoga gospodara. Poslije dugo vremena dođe gospodar onih slugu i zatraži od njih račun. I pristupi onaj koji je primio pet talenata, donese drugih pet talenata i reče: Gospodaru, predao si mi pet talenata. Stekao sam s njima drugih pet. Gospodar mu odgovori: Dobro, slugo dobri i vjerni, jer si bio vjeran u malom, postavit ću te nad mnogim: Uđi u veselje svoga gospodara! A pristupi i onaj koji je primio dva talenta i reče: Gospodaru, predao si mi dva talenta. Stekao sam s njima druga dva. Gospodar mu odgovori: Dobro, slugo dobri i vjerni, jer si bio vjeran u malome, postavit ću te nad mnogim: Uđi u veselje svoga gospodara!","kn":"t Slijedi sveto evanđelje po Mateju (25, 14-23), U ono vrijeme reče Isus svojim učenicima ovu prisjpodobu; Čovjek, koji kreće na put, pozove svoje sluge i preda im svoj imetak. Jednomu dade pet talenata, drugomu dva, a trećemu jedan; svakomu prema njegovoj sposobnosti. I odmah otputuje. Onaj, koji je primio pet talenata, ode, da s njima radi i steče drugih pet. Tako i koji je primio dva, steče s njima druga dva. A koji je primio jedan, ode, zakopa i sakrije novac svoga gospodara. Poslije dugo vremena dođe gospodar onih slugu i zatraži od njih račun. I pristupi onaj, koji je primio pet talenata, donese drugih pet talenata i reče: Gospodaru, predao si mi pet talenata. Stekao sam s njima drugih pet. Gospodar mu odgovori: Dobro, slugo dobri i vjerni, jer si bio vjeran u malom, postavit ću te nad mnogim: Uđi u veselje svoga gospodara! A pristupi i onaj, koji je primio dva talenta i reče: Gospodaru, predao si mi dva talenta. Stekao sam s njima druga dva. Gospodar mu odgovori; Dobro, slugo dobri i vjerni, jer si bio vjeran u malom, postavit ću te nad mnogim; Uđi u veselje svoga gospodara! Vjerujem.","knRef":"Kniewald 1942, str. 626–627 (snimka 314) (OCR)"},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć.","kn":"(Ps. 88, 25). Istina je moja i milosrđe moje B njime i u ime će se moje uzdići moć njegova.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"2551a15508499727":{"t":"Posveti, molimo, Gospodine Bože, ove darove koje ti prikazujemo o svetkovini svetoga tvog biskupa Nikole, da se život naš u sreći i nesreći svagdje ravna po njima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Posveti, molimo. Gospodine, Bože naš, ove darove, što Ti ih prinosimo o blagdanu svetoga Tvoga biskupa Nikole, da oni vazda upravljaju našim životom, u sreći i nesreći, po G. n.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"3eefd390cb354c24":{"t":"Ps 88, 36-38\nZakleo sam se svecu svome: Potomstvo će njegovo ostati dovijeka. I prijestolje će njegovo biti kao sunce, kao puni mjesec u vijeke i kao duga koja je vjeran znak na nebesima.","kn":"(Ps. 88, 36-38). Jednom se zakleh svetošću svojom: potomstvo će njegovo ostati u vijeke, i prijesto njegov kao sunce pred licem mojim, i kao mjesec, koji je osnovan u vijeke; i svjedok je na nebu vjeran.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"878749af285b70de":{"t":"<i>Pomolimo se</i>.\nŽrtve koje smo primili, Gospodine, o svetkovini svetoga tvog biskupa Nikole neka nas čuvaju neprestanom zaštitom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Žrtve, što ih užismo, Gosipodine, u čast blagdana Tvoga svetoga biskupa Nikole, neka nas čuvaju neprestanom zaštitom. Po G. n.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"}}});
